import { API_FUNCTIONS } from './spec.ts';

export function generateTypeScript(): string {
  const lines: string[] = [
    '/* Automatically generated by Galfus Engine codegen. Do not edit directly. */',
    '',
    'export interface PlatformCapabilities {',
    '  supportsMultipleWindows: boolean;',
    '  supportsWindowPositioning: boolean;',
    '  supportsCursorGrab: boolean;',
    '  supportsGamepad: boolean;',
    '  supportsAudio: boolean;',
    '  isHeadless: boolean;',
    '}',
    '',
    'export interface WindowConfig {',
    '  id: number;',
    '  title: string;',
    '  size?: [number, number];',
    '  position?: [number, number];',
    '  resizable?: boolean;',
    '  decorations?: boolean;',
    '  transparent?: boolean;',
    '  initialState?: "windowed" | "minimized" | "maximized" | "fullscreen" | "borderlessFullscreen";',
    '  canvasId?: string;',
    '}',
    '',
    'export type PointerType = "mouse" | "touch" | "pen";',
    'export type PointerButton = "primary" | "secondary" | "auxiliary" | "back" | "forward" | { other: number };',
    'export type PointerButtonState = "pressed" | "released";',
    '',
    'export type ScrollDelta =',
    '  | { lines: [number, number] }',
    '  | { pixels: [number, number] };',
    '',
    'export type PointerEvent =',
    '  | {',
    '      move: {',
    '        windowId: number;',
    '        pointerId: number;',
    '        pointerType: PointerType;',
    '        position: [number, number];',
    '        delta: [number, number];',
    '        pressure: number;',
    '      };',
    '    }',
    '  | {',
    '      button: {',
    '        windowId: number;',
    '        pointerId: number;',
    '        pointerType: PointerType;',
    '        position: [number, number];',
    '        button: PointerButton;',
    '        state: PointerButtonState;',
    '        pressure: number;',
    '      };',
    '    }',
    '  | {',
    '      enter: {',
    '        windowId: number;',
    '        pointerId: number;',
    '        pointerType: PointerType;',
    '        position: [number, number];',
    '      };',
    '    }',
    '  | {',
    '      leave: {',
    '        windowId: number;',
    '        pointerId: number;',
    '        pointerType: PointerType;',
    '        position: [number, number];',
    '      };',
    '    }',
    '  | {',
    '      cancel: {',
    '        windowId: number;',
    '        pointerId: number;',
    '        pointerType: PointerType;',
    '        position: [number, number];',
    '      };',
    '    }',
    '  | {',
    '      scroll: {',
    '        windowId: number;',
    '        pointerId: number;',
    '        pointerType: PointerType;',
    '        position: [number, number];',
    '        delta: ScrollDelta;',
    '      };',
    '    };',
    '',
    'export interface ModifiersState {',
    '  shift: boolean;',
    '  ctrl: boolean;',
    '  alt: boolean;',
    '  superKey: boolean;',
    '}',
    '',
    'export type KeyboardEvent =',
    '  | {',
    '      input: {',
    '        windowId: number;',
    '        physicalKey: string;',
    '        logicalKey: string | { named: string };',
    '        text?: string;',
    '        state: "pressed" | "released";',
    '        modifiers: ModifiersState;',
    '        repeat: boolean;',
    '      };',
    '    }',
    '  | {',
    '      modifiersChanged: {',
    '        windowId: number;',
    '        modifiers: ModifiersState;',
    '      };',
    '    };',
    '',
    'export type WindowEvent =',
    '  | { resized: { windowId: number; width: number; height: number; scaleFactor: number } }',
    '  | { moved: { windowId: number; x: number; y: number } }',
    '  | { closeRequested: { windowId: number } }',
    '  | { focusChanged: { windowId: number; focused: boolean } }',
    '  | { occluded: { windowId: number; occluded: boolean } }',
    '  | { scaleFactorChanged: { windowId: number; scaleFactor: number } }',
    '  | { redrawRequested: { windowId: number } };',
    '',
    'export type PlatformEvent =',
    '  | { window: WindowEvent }',
    '  | { pointer: PointerEvent }',
    '  | { keyboard: KeyboardEvent };',
    '',
    '/** Native interface signature exposed by Galfus Engine (Node-API / Bun). */',
    'export interface GalfusEngine {'
  ];

  for (const fn of API_FUNCTIONS) {
    const isConfigCall = fn.params.some((p) => p.name === 'configJson' || p.name === 'config');
    const paramsList: string[] = [];

    for (const p of fn.params) {
      if (p.name === 'configJson' || p.name === 'config') {
        paramsList.push(`${p.name}: WindowConfig`);
      } else if (p.type === 'string_in') {
        paramsList.push(`${p.name}: string`);
      } else if (p.type === 'i32' || p.type === 'u32') {
        paramsList.push(`${p.name}: number`);
      } else if (p.type === 'bool') {
        paramsList.push(`${p.name}: boolean`);
      } else {
        paramsList.push(`${p.name}: any`);
      }
    }

    let retType = 'void';
    if (fn.returnsJson) {
      if (fn.methodName === 'platformGetCapabilities') {
        retType = 'PlatformCapabilities';
      } else if (fn.methodName === 'platformPumpEvents') {
        retType = 'PlatformEvent[]';
      } else {
        retType = 'any';
      }
    } else if (fn.returnType === 'string_out') {
      retType = 'string';
    } else if (isConfigCall) {
      retType = 'number';
    }

    lines.push(`  /** ${fn.doc} */`);
    lines.push(`  ${fn.methodName}(${paramsList.join(', ')}): ${retType};`);
  }

  lines.push('}', '');

  return lines.join('\n');
}
